/* From Uiverse.io by arshshaikh06 - Source: https://codepen.io/arsh-shaikh/pen/ZELZwWq?editors=1100 - Tags: card, palette, ui, card hover */
.__UIV_SCOPE__ .container {
  height: 200px;
  width: 350px;
  border-radius: 1em;
  overflow: hidden;
  box-shadow: 0 10px 20px #dbdbdb;
  font-family: sans-serif;
}

.__UIV_SCOPE__ .palette {
  display: flex;
  height: 86%;
  width: 100%;
}

.__UIV_SCOPE__ .color {
  height: 100%;
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-weight: 600;
  letter-spacing: 1px;
  transition: flex 0.1s linear;
}

.__UIV_SCOPE__ .color span {
  opacity: 0;
  transition: opacity 0.1s linear;
}

.__UIV_SCOPE__ .color:nth-child(1) {
  background: #264653;
}

.__UIV_SCOPE__ .color:nth-child(2) {
  background: #2a9d8f;
}

.__UIV_SCOPE__ .color:nth-child(3) {
  background: #e9c46a;
}

.__UIV_SCOPE__ .color:nth-child(4) {
  background: #f4a261;
}

.__UIV_SCOPE__ .color:nth-child(5) {
  background: #e76f51;
}

.__UIV_SCOPE__ .color:hover {
  flex: 2;
  box-shadow: rgba(100, 100, 111, 0.2) 0px 7px 29px 0px;
}

.__UIV_SCOPE__ .color:hover span {
  opacity: 1;
}

.__UIV_SCOPE__ #stats {
  height: 14%;
  width: 100%;
  background: white;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 1.5em;
  box-sizing: border-box;
  color: #bebebe;
}

.__UIV_SCOPE__ #stats svg {
  fill: #bebebe;
  transform: scale(1.2);
}
